head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf30003";
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_datefmt_cal_strtDd
 * @description 초기화 — datefmt cal strt Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_strtDd = function () { $c.date.checkCalendarFormat("cal_strtDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {

        /*달력셋팅*/

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf30003.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":5
        ,"mmenu":9
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf30003' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_datefmt_cal_strtDd();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf30003.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_searchStripYdList_onclick
 * @description btn_searchStripYdList 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchStripYdList_onclick = async function(e){
    try {
        await scwin.searchStripYdList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf30003.btn_searchStripYdList_onclick' }); }
};

/**
 * @method
 * @name btn_close_onclick
 * @description btn_close 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_close_onclick = function(e){
    try {
        scwin.close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf30003.btn_close_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchStripYdList
 * @description search Strip Yd List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchStripYdList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchStripYdList",
        method: "post",
        action: "/strip/strip.do?method=searchStripYdList",
        ref: "dma_searchStripYdListReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name searchStripYdList
 * @description search Strip Yd List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchStripYdList = async function () {
    const fm = (document.searchForm || { elements: [] });
    let _previewWindow;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    _previewWindow = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/strip/strip.do?method=searchStripYdList", unresolved: "nav:" + "/strip/strip.do?method=searchStripYdList" }; })();
    fm.action = '/strip/strip.do?method=searchStripYdList';

    return;
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    $c.win.closePopup();
};
